'use client'

import { IconSearch, IconX } from '@tabler/icons-react'
import { useState } from 'react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
  Combobox,
  ComboboxEmpty,
  ComboboxInput,
  ComboboxItem,
  ComboboxList,
  ComboboxPopup,
} from '@/components/ui/combobox'

type TeamMember = {
  avatar: string
  initials: string
  label: string
  priority: 'Lowest' | 'Low' | 'Medium' | 'High' | 'Highest'
  value: string
  weight: number
}

const teamMembers: TeamMember[] = [
  {
    avatar: 'https://avatars.spaceui.one/v1?name=orion&variant=titan',
    initials: 'JH',
    label: 'Jenny Hamilton',
    priority: 'Highest',
    value: 'jenny',
    weight: 200,
  },
  {
    avatar: 'https://avatars.spaceui.one/v1?name=lyra&variant=glass',
    initials: 'PS',
    label: 'Paul Smith',
    priority: 'Medium',
    value: 'paul',
    weight: 100,
  },
  {
    avatar: 'https://avatars.spaceui.one/v1?name=vega&variant=pebble',
    initials: 'LW',
    label: 'Luna Wyen',
    priority: 'High',
    value: 'luna',
    weight: 150,
  },
  {
    avatar: 'https://avatars.spaceui.one/v1?name=sirius&variant=invader',
    initials: 'AC',
    label: 'Alex Chen',
    priority: 'Low',
    value: 'alex',
    weight: 100,
  },
  {
    avatar: 'https://avatars.spaceui.one/v1?name=nova&variant=kendo',
    initials: 'SJ',
    label: 'Sarah Johnson',
    priority: 'Medium',
    value: 'sarah',
    weight: 50,
  },
  {
    avatar: 'https://avatars.spaceui.one/v1?name=pulsar&variant=lumina',
    initials: 'ED',
    label: 'Emma Davis',
    priority: 'Lowest',
    value: 'emma',
    weight: 100,
  },
]

export default function Demo() {
  const [open, setOpen] = useState(false)
  const [selected, setSelected] = useState<TeamMember[]>(teamMembers.slice(0, 2))

  return (
    <div className="flex w-full flex-col gap-2">
      <Combobox
        autoHighlight
        items={teamMembers}
        multiple
        onOpenChange={setOpen}
        onValueChange={(value) => {
          setSelected(value)
          setOpen(false)
        }}
        open={open}
        value={selected}
      >
        <ComboboxInput aria-label="Add team members" placeholder="Add team members…" startAddon={<IconSearch />} />
        <ComboboxPopup>
          <ComboboxEmpty>No team members found.</ComboboxEmpty>
          <ComboboxList>
            {(item: TeamMember) => (
              <ComboboxItem key={item.value} value={item}>
                {item.label}
              </ComboboxItem>
            )}
          </ComboboxList>
        </ComboboxPopup>
      </Combobox>
      {selected.length > 0 && (
        <ul className="flex flex-col gap-2">
          {selected.map((member) => (
            <li
              className="flex items-center gap-2 rounded-lg border border-input p-1 ps-2 text-base sm:text-sm"
              key={member.value}
            >
              <Avatar className="size-5">
                <AvatarImage alt={member.label} src={member.avatar} />
                <AvatarFallback className="text-[.625rem]">{member.initials}</AvatarFallback>
              </Avatar>
              <span className="truncate font-medium">{member.label}</span>
              <Badge className="ms-auto" variant="info">
                {member.priority}
              </Badge>
              <span className="text-muted-foreground tabular-nums">{member.weight}%</span>
              <Button
                aria-label={`Remove ${member.label}`}
                onClick={() => setSelected((current) => current.filter((item) => item.value !== member.value))}
                size="icon-xs"
                variant="ghost"
              >
                <IconX />
              </Button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}
